package com.logatron.investigation.infrastructure;
import com.fasterxml.jackson.databind.ObjectMapper;import com.logatron.auth.application.EffectiveScope;import com.logatron.investigation.configuration.InvestigationProperties;import com.logatron.investigation.domain.InvestigationModels.*;import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;import static org.assertj.core.api.Assertions.assertThat;
class PrometheusMetricQueryAdapterTest {private HttpServer server;private final AtomicReference<String> query=new AtomicReference<>();private final UUID project=UUID.randomUUID(),environment=UUID.randomUUID();@BeforeEach void start()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/api/v1/query_range",exchange->{query.set(URLDecoder.decode(exchange.getRequestURI().getRawQuery(),StandardCharsets.UTF_8));byte[] body=("{\"status\":\"success\",\"data\":{\"resultType\":\"matrix\",\"result\":[{\"metric\":{\"service\":\"settlement-service\"},\"values\":[[1788066540,\"1.0\"]]}]}}").getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,body.length);exchange.getResponseBody().write(body);exchange.close();});server.start();}@AfterEach void stop(){server.stop(0);}
 @Test void buildsOnlyAllowlistedScopedPromQl(){var adapter=new PrometheusMetricQueryAdapter(properties(),new ObjectMapper());var result=adapter.query(scope(),request(),Set.of(MetricOperation.DB_POOL_USAGE_RATIO));assertThat(result).singleElement().satisfies(v->{assertThat(v.operation()).isEqualTo(MetricOperation.DB_POOL_USAGE_RATIO);assertThat(v.service()).isEqualTo("settlement-service");});assertThat(query.get()).contains("project_id=\""+project+"\"").contains("environment_id=\""+environment+"\"").doesNotContain("\\\"");}
 @Test void unsupportedOperationDoesNotReachPrometheus(){var adapter=new PrometheusMetricQueryAdapter(properties(),new ObjectMapper());assertThat(adapter.query(scope(),request(),Set.of(MetricOperation.HOST_CPU_USAGE))).isEmpty();assertThat(query.get()).isNull();}
 private InvestigationProperties properties(){return new InvestigationProperties("http://127.0.0.1:"+server.getAddress().getPort(),Duration.ofSeconds(2),20,true,"stub","v1");}private InvestigationQuery request(){return new InvestigationQuery(project,environment,Instant.parse("2026-08-30T10:00:00Z"),Instant.parse("2026-08-30T10:30:00Z"),IdentifierType.ORDER_TOKEN,"order-42");}private EffectiveScope scope(){return new EffectiveScope(false,Map.of(project,new EffectiveScope.ProjectScope(project,Set.of(),Set.of(environment),Map.of(),false)));}}
